    // illegal characters ('foo') and Value::Int(ccxt::runtime::TICK_SIZE) with negative numPrecisionDigits must all throw
    // ----------------------------------------------------------------------------
    // Additional Edge Cases
    // Zero handling variations
    assert!(ccxt::runtime::is_true(&(Value::Bool(exchange.decimal_to_precision(Value::Str("0.0".into()), Value::Int(ccxt::runtime::TRUNCATE), Value::Int(2), &[Value::Int(ccxt::runtime::DECIMAL_PLACES)]).as_str() == Some("0")))));
    assert!(ccxt::runtime::is_true(&(Value::Bool(exchange.decimal_to_precision(Value::Str("0.00".into()), Value::Int(ccxt::runtime::ROUND), Value::Int(3), &[Value::Int(ccxt::runtime::DECIMAL_PLACES), Value::Int(ccxt::runtime::PAD_WITH_ZERO)]).as_str() == Some("0.000")))));
    assert!(ccxt::runtime::is_true(&(Value::Bool(exchange.decimal_to_precision(Value::Str("-0.0".into()), Value::Int(ccxt::runtime::TRUNCATE), Value::Int(2), &[Value::Int(ccxt::runtime::DECIMAL_PLACES)]).as_str() == Some("0")))));
    assert!(ccxt::runtime::is_true(&(Value::Bool(exchange.decimal_to_precision(Value::Str("-0.00".into()), Value::Int(ccxt::runtime::ROUND), Value::Int(1), &[Value::Int(ccxt::runtime::DECIMAL_PLACES)]).as_str() == Some("0")))));
    // Very small numbers close to zero
    assert!(ccxt::runtime::is_true(&(Value::Bool(exchange.decimal_to_precision(Value::Str("0.0000000001".into()), Value::Int(ccxt::runtime::TRUNCATE), Value::Int(8), &[Value::Int(ccxt::runtime::DECIMAL_PLACES)]).as_str() == Some("0")))));
    assert!(ccxt::runtime::is_true(&(Value::Bool(exchange.decimal_to_precision(Value::Str("0.0000000001".into()), Value::Int(ccxt::runtime::ROUND), Value::Int(8), &[Value::Int(ccxt::runtime::DECIMAL_PLACES)]).as_str() == Some("0")))));
    assert!(ccxt::runtime::is_true(&(Value::Bool(exchange.decimal_to_precision(Value::Str("0.0000000001".into()), Value::Int(ccxt::runtime::TRUNCATE), Value::Int(10), &[Value::Int(ccxt::runtime::DECIMAL_PLACES)]).as_str() == Some("0.0000000001")))));
    assert!(ccxt::runtime::is_true(&(Value::Bool(exchange.decimal_to_precision(Value::Str("0.00000000009".into()), Value::Int(ccxt::runtime::ROUND), Value::Int(10), &[Value::Int(ccxt::runtime::DECIMAL_PLACES)]).as_str() == Some("0.0000000001")))));
    assert!(ccxt::runtime::is_true(&(Value::Bool(exchange.decimal_to_precision(Value::Str("0.00000000015".into()), Value::Int(ccxt::runtime::ROUND), Value::Int(10), &[Value::Int(ccxt::runtime::DECIMAL_PLACES)]).as_str() == Some("0.0000000002")))));
    // Very large numbers
    assert!(ccxt::runtime::is_true(&(Value::Bool(exchange.decimal_to_precision(Value::Str("99999999999999.99999".into()), Value::Int(ccxt::runtime::TRUNCATE), Value::Int(2), &[Value::Int(ccxt::runtime::DECIMAL_PLACES)]).as_str() == Some("99999999999999.99")))));
    assert!(ccxt::runtime::is_true(&(Value::Bool(exchange.decimal_to_precision(Value::Str("99999999999999.99999".into()), Value::Int(ccxt::runtime::ROUND), Value::Int(2), &[Value::Int(ccxt::runtime::DECIMAL_PLACES)]).as_str() == Some("100000000000000")))));
    assert!(ccxt::runtime::is_true(&(Value::Bool(exchange.decimal_to_precision(Value::Str("123456789012345".into()), Value::Int(ccxt::runtime::TRUNCATE), Value::Int(3), &[Value::Int(ccxt::runtime::SIGNIFICANT_DIGITS)]).as_str() == Some("123000000000000")))));
    assert!(ccxt::runtime::is_true(&(Value::Bool(exchange.decimal_to_precision(Value::Str("123456789012345".into()), Value::Int(ccxt::runtime::ROUND), Value::Int(3), &[Value::Int(ccxt::runtime::SIGNIFICANT_DIGITS)]).as_str() == Some("123000000000000")))));
    // Numbers with leading zeros
    assert!(ccxt::runtime::is_true(&(Value::Bool(exchange.decimal_to_precision(Value::Str("000123.456".into()), Value::Int(ccxt::runtime::TRUNCATE), Value::Int(2), &[Value::Int(ccxt::runtime::DECIMAL_PLACES)]).as_str() == Some("123.45")))));
    assert!(ccxt::runtime::is_true(&(Value::Bool(exchange.decimal_to_precision(Value::Str("000123.456".into()), Value::Int(ccxt::runtime::ROUND), Value::Int(2), &[Value::Int(ccxt::runtime::DECIMAL_PLACES)]).as_str() == Some("123.46")))));
    assert!(ccxt::runtime::is_true(&(Value::Bool(exchange.decimal_to_precision(Value::Str("0000.123".into()), Value::Int(ccxt::runtime::TRUNCATE), Value::Int(2), &[Value::Int(ccxt::runtime::DECIMAL_PLACES)]).as_str() == Some("0.12")))));
    // Boundary rounding cases (exactly at 0.5)
    assert!(ccxt::runtime::is_true(&(Value::Bool(exchange.decimal_to_precision(Value::Str("1.5".into()), Value::Int(ccxt::runtime::ROUND), Value::Int(0), &[Value::Int(ccxt::runtime::DECIMAL_PLACES)]).as_str() == Some("2")))));
    assert!(ccxt::runtime::is_true(&(Value::Bool(exchange.decimal_to_precision(Value::Str("2.5".into()), Value::Int(ccxt::runtime::ROUND), Value::Int(0), &[Value::Int(ccxt::runtime::DECIMAL_PLACES)]).as_str() == Some("3")))));
    assert!(ccxt::runtime::is_true(&(Value::Bool(exchange.decimal_to_precision(Value::Str("-1.5".into()), Value::Int(ccxt::runtime::ROUND), Value::Int(0), &[Value::Int(ccxt::runtime::DECIMAL_PLACES)]).as_str() == Some("-2")))));
    assert!(ccxt::runtime::is_true(&(Value::Bool(exchange.decimal_to_precision(Value::Str("-2.5".into()), Value::Int(ccxt::runtime::ROUND), Value::Int(0), &[Value::Int(ccxt::runtime::DECIMAL_PLACES)]).as_str() == Some("-3")))));
    assert!(ccxt::runtime::is_true(&(Value::Bool(exchange.decimal_to_precision(Value::Str("1.25".into()), Value::Int(ccxt::runtime::ROUND), Value::Int(1), &[Value::Int(ccxt::runtime::DECIMAL_PLACES)]).as_str() == Some("1.3")))));
    assert!(ccxt::runtime::is_true(&(Value::Bool(exchange.decimal_to_precision(Value::Str("1.35".into()), Value::Int(ccxt::runtime::ROUND), Value::Int(1), &[Value::Int(ccxt::runtime::DECIMAL_PLACES)]).as_str() == Some("1.4")))));
    // Carry-over in rounding (cascading effects)
    assert!(ccxt::runtime::is_true(&(Value::Bool(exchange.decimal_to_precision(Value::Str("9.999999".into()), Value::Int(ccxt::runtime::ROUND), Value::Int(0), &[Value::Int(ccxt::runtime::DECIMAL_PLACES)]).as_str() == Some("10")))));
    assert!(ccxt::runtime::is_true(&(Value::Bool(exchange.decimal_to_precision(Value::Str("99.999999".into()), Value::Int(ccxt::runtime::ROUND), Value::Int(0), &[Value::Int(ccxt::runtime::DECIMAL_PLACES)]).as_str() == Some("100")))));
    assert!(ccxt::runtime::is_true(&(Value::Bool(exchange.decimal_to_precision(Value::Str("999.999999".into()), Value::Int(ccxt::runtime::ROUND), Value::Int(0), &[Value::Int(ccxt::runtime::DECIMAL_PLACES)]).as_str() == Some("1000")))));
    assert!(ccxt::runtime::is_true(&(Value::Bool(exchange.decimal_to_precision(Value::Str("9.999999".into()), Value::Int(ccxt::runtime::ROUND), Value::Int(1), &[Value::Int(ccxt::runtime::DECIMAL_PLACES)]).as_str() == Some("10")))));
    assert!(ccxt::runtime::is_true(&(Value::Bool(exchange.decimal_to_precision(Value::Str("9.999999".into()), Value::Int(ccxt::runtime::ROUND), Value::Int(2), &[Value::Int(ccxt::runtime::DECIMAL_PLACES)]).as_str() == Some("10")))));
    assert!(ccxt::runtime::is_true(&(Value::Bool(exchange.decimal_to_precision(Value::Str("-9.999999".into()), Value::Int(ccxt::runtime::ROUND), Value::Int(0), &[Value::Int(ccxt::runtime::DECIMAL_PLACES)]).as_str() == Some("-10")))));
    assert!(ccxt::runtime::is_true(&(Value::Bool(exchange.decimal_to_precision(Value::Str("-99.999999".into()), Value::Int(ccxt::runtime::ROUND), Value::Int(0), &[Value::Int(ccxt::runtime::DECIMAL_PLACES)]).as_str() == Some("-100")))));
    // Edge cases for Value::Int(ccxt::runtime::TICK_SIZE) with very small ticks
    assert!(ccxt::runtime::is_true(&(Value::Bool(exchange.decimal_to_precision(Value::Str("1.2345".into()), Value::Int(ccxt::runtime::ROUND), Value::Float(0.0001), &[Value::Int(ccxt::runtime::TICK_SIZE)]).as_str() == Some("1.2345")))));
    assert!(ccxt::runtime::is_true(&(Value::Bool(exchange.decimal_to_precision(Value::Str("1.23456".into()), Value::Int(ccxt::runtime::ROUND), Value::Float(0.0001), &[Value::Int(ccxt::runtime::TICK_SIZE)]).as_str() == Some("1.2346")))));
    assert!(ccxt::runtime::is_true(&(Value::Bool(exchange.decimal_to_precision(Value::Str("1.23454".into()), Value::Int(ccxt::runtime::ROUND), Value::Float(0.0001), &[Value::Int(ccxt::runtime::TICK_SIZE)]).as_str() == Some("1.2345")))));
    assert!(ccxt::runtime::is_true(&(Value::Bool(exchange.decimal_to_precision(Value::Str("1.23444".into()), Value::Int(ccxt::runtime::TRUNCATE), Value::Float(0.0001), &[Value::Int(ccxt::runtime::TICK_SIZE)]).as_str() == Some("1.2344")))));
    // Value::Int(ccxt::runtime::TICK_SIZE) with numbers smaller than tick
    assert!(ccxt::runtime::is_true(&(Value::Bool(exchange.decimal_to_precision(Value::Str("0.05".into()), Value::Int(ccxt::runtime::ROUND), Value::Float(0.1), &[Value::Int(ccxt::runtime::TICK_SIZE)]).as_str() == Some("0.1")))));
    assert!(ccxt::runtime::is_true(&(Value::Bool(exchange.decimal_to_precision(Value::Str("0.04".into()), Value::Int(ccxt::runtime::ROUND), Value::Float(0.1), &[Value::Int(ccxt::runtime::TICK_SIZE)]).as_str() == Some("0")))));
    assert!(ccxt::runtime::is_true(&(Value::Bool(exchange.decimal_to_precision(Value::Str("0.04".into()), Value::Int(ccxt::runtime::TRUNCATE), Value::Float(0.1), &[Value::Int(ccxt::runtime::TICK_SIZE)]).as_str() == Some("0")))));
    assert!(ccxt::runtime::is_true(&(Value::Bool(exchange.decimal_to_precision(Value::Str("0.049999".into()), Value::Int(ccxt::runtime::ROUND), Value::Float(0.1), &[Value::Int(ccxt::runtime::TICK_SIZE)]).as_str() == Some("0")))));
    // Value::Int(ccxt::runtime::SIGNIFICANT_DIGITS) edge cases
    assert!(ccxt::runtime::is_true(&(Value::Bool(exchange.decimal_to_precision(Value::Str("10000000".into()), Value::Int(ccxt::runtime::TRUNCATE), Value::Int(1), &[Value::Int(ccxt::runtime::SIGNIFICANT_DIGITS)]).as_str() == Some("10000000")))));
    assert!(ccxt::runtime::is_true(&(Value::Bool(exchange.decimal_to_precision(Value::Str("10000001".into()), Value::Int(ccxt::runtime::TRUNCATE), Value::Int(1), &[Value::Int(ccxt::runtime::SIGNIFICANT_DIGITS)]).as_str() == Some("10000000")))));
    assert!(ccxt::runtime::is_true(&(Value::Bool(exchange.decimal_to_precision(Value::Str("19999999".into()), Value::Int(ccxt::runtime::TRUNCATE), Value::Int(1), &[Value::Int(ccxt::runtime::SIGNIFICANT_DIGITS)]).as_str() == Some("10000000")))));
    assert!(ccxt::runtime::is_true(&(Value::Bool(exchange.decimal_to_precision(Value::Str("19999999".into()), Value::Int(ccxt::runtime::ROUND), Value::Int(1), &[Value::Int(ccxt::runtime::SIGNIFICANT_DIGITS)]).as_str() == Some("20000000")))));
    // Precision with Value::Int(ccxt::runtime::PAD_WITH_ZERO) edge cases
    assert!(ccxt::runtime::is_true(&(Value::Bool(exchange.decimal_to_precision(Value::Str("1".into()), Value::Int(ccxt::runtime::TRUNCATE), Value::Int(0), &[Value::Int(ccxt::runtime::DECIMAL_PLACES), Value::Int(ccxt::runtime::PAD_WITH_ZERO)]).as_str() == Some("1")))));
    assert!(ccxt::runtime::is_true(&(Value::Bool(exchange.decimal_to_precision(Value::Str("1.0".into()), Value::Int(ccxt::runtime::TRUNCATE), Value::Int(0), &[Value::Int(ccxt::runtime::DECIMAL_PLACES), Value::Int(ccxt::runtime::PAD_WITH_ZERO)]).as_str() == Some("1")))));
    assert!(ccxt::runtime::is_true(&(Value::Bool(exchange.decimal_to_precision(Value::Str("1".into()), Value::Int(ccxt::runtime::TRUNCATE), Value::Int(3), &[Value::Int(ccxt::runtime::DECIMAL_PLACES), Value::Int(ccxt::runtime::PAD_WITH_ZERO)]).as_str() == Some("1.000")))));
    assert!(ccxt::runtime::is_true(&(Value::Bool(exchange.decimal_to_precision(Value::Str("1.1".into()), Value::Int(ccxt::runtime::TRUNCATE), Value::Int(5), &[Value::Int(ccxt::runtime::DECIMAL_PLACES), Value::Int(ccxt::runtime::PAD_WITH_ZERO)]).as_str() == Some("1.10000")))));
    // Numbers that are exactly multiples of precision
    assert!(ccxt::runtime::is_true(&(Value::Bool(exchange.decimal_to_precision(Value::Str("1.2".into()), Value::Int(ccxt::runtime::TRUNCATE), Value::Float(0.1), &[Value::Int(ccxt::runtime::TICK_SIZE)]).as_str() == Some("1.2")))));
    assert!(ccxt::runtime::is_true(&(Value::Bool(exchange.decimal_to_precision(Value::Str("1.2".into()), Value::Int(ccxt::runtime::ROUND), Value::Float(0.1), &[Value::Int(ccxt::runtime::TICK_SIZE)]).as_str() == Some("1.2")))));
    assert!(ccxt::runtime::is_true(&(Value::Bool(exchange.decimal_to_precision(Value::Str("12".into()), Value::Int(ccxt::runtime::TRUNCATE), Value::Int(4), &[Value::Int(ccxt::runtime::TICK_SIZE)]).as_str() == Some("12")))));
    assert!(ccxt::runtime::is_true(&(Value::Bool(exchange.decimal_to_precision(Value::Str("12".into()), Value::Int(ccxt::runtime::ROUND), Value::Int(4), &[Value::Int(ccxt::runtime::TICK_SIZE)]).as_str() == Some("12")))));
    // Very high precision values
    assert!(ccxt::runtime::is_true(&(Value::Bool(exchange.decimal_to_precision(Value::Str("1.123456789012345".into()), Value::Int(ccxt::runtime::TRUNCATE), Value::Int(15), &[Value::Int(ccxt::runtime::DECIMAL_PLACES)]).as_str() == Some("1.123456789012345")))));
    assert!(ccxt::runtime::is_true(&(Value::Bool(exchange.decimal_to_precision(Value::Str("1.123456789012345".into()), Value::Int(ccxt::runtime::TRUNCATE), Value::Int(10), &[Value::Int(ccxt::runtime::DECIMAL_PLACES)]).as_str() == Some("1.123456789")))));
    assert!(ccxt::runtime::is_true(&(Value::Bool(exchange.decimal_to_precision(Value::Str("1.123456789012345".into()), Value::Int(ccxt::runtime::TRUNCATE), Value::Int(10), &[Value::Int(ccxt::runtime::DECIMAL_PLACES), Value::Int(ccxt::runtime::PAD_WITH_ZERO)]).as_str() == Some("1.1234567890")))));
    assert!(ccxt::runtime::is_true(&(Value::Bool(exchange.decimal_to_precision(Value::Str("0.123456789012345".into()), Value::Int(ccxt::runtime::TRUNCATE), Value::Int(15), &[Value::Int(ccxt::runtime::SIGNIFICANT_DIGITS)]).as_str() == Some("0.123456789012345")))));
    // Mixed large and small components
    assert!(ccxt::runtime::is_true(&(Value::Bool(exchange.decimal_to_precision(Value::Str("1000000.000001".into()), Value::Int(ccxt::runtime::TRUNCATE), Value::Int(6), &[Value::Int(ccxt::runtime::DECIMAL_PLACES)]).as_str() == Some("1000000.000001")))));
    assert!(ccxt::runtime::is_true(&(Value::Bool(exchange.decimal_to_precision(Value::Str("1000000.000001".into()), Value::Int(ccxt::runtime::TRUNCATE), Value::Int(5), &[Value::Int(ccxt::runtime::DECIMAL_PLACES), Value::Int(ccxt::runtime::PAD_WITH_ZERO)]).as_str() == Some("1000000.00000")))));
    assert!(ccxt::runtime::is_true(&(Value::Bool(exchange.decimal_to_precision(Value::Str("1000000.000001".into()), Value::Int(ccxt::runtime::ROUND), Value::Int(5), &[Value::Int(ccxt::runtime::DECIMAL_PLACES), Value::Int(ccxt::runtime::PAD_WITH_ZERO)]).as_str() == Some("1000000.00000")))));
    // Edge cases around 1.0 boundary for significant digits
    assert!(ccxt::runtime::is_true(&(Value::Bool(exchange.decimal_to_precision(Value::Str("0.999999".into()), Value::Int(ccxt::runtime::ROUND), Value::Int(1), &[Value::Int(ccxt::runtime::SIGNIFICANT_DIGITS)]).as_str() == Some("1")))));
    assert!(ccxt::runtime::is_true(&(Value::Bool(exchange.decimal_to_precision(Value::Str("0.999999".into()), Value::Int(ccxt::runtime::ROUND), Value::Int(2), &[Value::Int(ccxt::runtime::SIGNIFICANT_DIGITS), Value::Int(ccxt::runtime::PAD_WITH_ZERO)]).as_str() == Some("1.0")))));
    assert!(ccxt::runtime::is_true(&(Value::Bool(exchange.decimal_to_precision(Value::Str("0.999999".into()), Value::Int(ccxt::runtime::ROUND), Value::Int(3), &[Value::Int(ccxt::runtime::SIGNIFICANT_DIGITS), Value::Int(ccxt::runtime::PAD_WITH_ZERO)]).as_str() == Some("1.00")))));
    assert!(ccxt::runtime::is_true(&(Value::Bool(exchange.decimal_to_precision(Value::Str("0.999949".into()), Value::Int(ccxt::runtime::ROUND), Value::Int(4), &[Value::Int(ccxt::runtime::SIGNIFICANT_DIGITS)]).as_str() == Some("0.9999")))));
    assert!(ccxt::runtime::is_true(&(Value::Bool(exchange.decimal_to_precision(Value::Str("0.999951".into()), Value::Int(ccxt::runtime::ROUND), Value::Int(4), &[Value::Int(ccxt::runtime::SIGNIFICANT_DIGITS), Value::Int(ccxt::runtime::PAD_WITH_ZERO)]).as_str() == Some("1.000")))));
    // ----------------------------------------------------------------------------
    // https://github.com/ccxt/ccxt/issues/11765
    assert!(ccxt::runtime::is_true(&(Value::Bool(exchange.decimal_to_precision(Value::Str("123456.12345678912".into()), Value::Int(ccxt::runtime::TRUNCATE), Value::Float(1e-8), &[Value::Int(ccxt::runtime::TICK_SIZE)]).as_str() == Some("123456.12345678")))));
    // todo: not sure about below
    assert!(ccxt::runtime::is_true(&(Value::Bool(exchange.decimal_to_precision(Value::Str("123456.12345674999".into()), Value::Int(ccxt::runtime::TRUNCATE), Value::Float(5e-8), &[Value::Int(ccxt::runtime::TICK_SIZE)]).as_str() == Some("123456.1234567")))));
    assert!(ccxt::runtime::is_true(&(Value::Bool(exchange.decimal_to_precision(Value::Str("123456.12345674999".into()), Value::Int(ccxt::runtime::TRUNCATE), Value::Float(5e-8), &[Value::Int(ccxt::runtime::TICK_SIZE), Value::Int(ccxt::runtime::PAD_WITH_ZERO)]).as_str() == Some("123456.12345670")))));
    assert!(ccxt::runtime::is_true(&(Value::Bool(exchange.decimal_to_precision(Value::Str("123456.12345675001".into()), Value::Int(ccxt::runtime::TRUNCATE), Value::Float(5e-8), &[Value::Int(ccxt::runtime::TICK_SIZE)]).as_str() == Some("123456.12345675")))));
    assert!(ccxt::runtime::is_true(&(Value::Bool(exchange.decimal_to_precision(Value::Str("123456.50000000001".into()), Value::Int(ccxt::runtime::TRUNCATE), Value::Float(0.5), &[Value::Int(ccxt::runtime::TICK_SIZE), Value::Int(ccxt::runtime::PAD_WITH_ZERO)]).as_str() == Some("123456.5")))));
    assert!(ccxt::runtime::is_true(&(Value::Bool(exchange.decimal_to_precision(Value::Str("123456.49999999999".into()), Value::Int(ccxt::runtime::TRUNCATE), Value::Float(0.5), &[Value::Int(ccxt::runtime::TICK_SIZE), Value::Int(ccxt::runtime::PAD_WITH_ZERO)]).as_str() == Some("123456.0")))));
    assert!(ccxt::runtime::is_true(&(Value::Bool(exchange.decimal_to_precision(Value::Str("123456.12345678912".into()), Value::Int(ccxt::runtime::TRUNCATE), Value::Str("0.00000001".into()), &[Value::Int(ccxt::runtime::TICK_SIZE)]).as_str() == Some("123456.12345678")))));
